"""Explain stack walk skip policies, lifetime pairing and reliable errors."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1949': ('길을 기록하는 도구 자신도 길 위에 나타날 수 있어요. 보고 싶은 호출 경로에서 도구 자신의 항목을 빼려고 한 칸을 추가로 건너뛰어요.', '현재 스택 수집의 추가 skip과 일반 콜백 선택을 이해합니다.', 'skipnr 2에 1을 더해 cookie.skip 3을 만드세요. 합성 주소 A·B·C·D에서 처음 세 개를 제외하면 D부터 저장해요.', ['stack_trace_save는 지금 실행 중인 태스크의 호출 경로를 저장해요. 태스크는 커널이 관리하는 실행 주체이고 current는 지금 실행 중인 태스크를 가리켜요. 여기서는 CONFIG_ARCH_STACKWALK 경로의 공통 구현을 읽어요.', 'skipnr는 호출한 쪽이 처음에서 건너뛰고 싶은 개수예요. 이 함수는 실제 수집 상태에 skipnr+1을 넣어요. 수집 함수 자신에 해당하는 항목을 제외하는 한 개를 더하는 정책이에요. skipnr가 0이어도 내부 skip은 1이에요.', 'skipnr=2라면 내부 skip은 3이에요. 용량이 충분한 합성 주소 A·B·C·D·E에서 A·B·C를 건너뛰고 D·E를 담는 예를 그릴 수 있어요. 이 가상 목록은 skip 계산을 보여 주며 실제 CPU의 모든 경로가 이런 항목 순서라는 보장은 아니에요.', '선택한 콜백은 stack_trace_consume_entry라는 일반 수집 함수예요. 이 함수는 용량과 skip을 확인해 저장해요. 스케줄러 주소를 별도 제외하는 nosched 콜백을 선택하지 않으므로 두 경로의 필터 정책을 같다고 생각하면 안 돼요.', 'arch_stack_walk에는 콜백, 수집 상태의 주소, current, NULL을 전달해요. 마지막 NULL은 별도의 저장 레지스터 출발점을 주지 않는다는 뜻이에요. 배열의 주소나 태스크까지 모두 NULL이라는 뜻이 아니에요.', '탐색이 끝나면 실제 저장 개수 c.len을 반환해요. 건너뛴 개수와 저장 개수는 다르므로 결과 배열에서는 반환 개수만큼만 읽어요. 이 예는 작은 유효 skipnr를 사용하며 표현 범위를 넘는 덧셈까지 같은 의미로 가정하지 않아요.'], [('현재 스택 저장에서 skipnr가 2이면 내부 cookie.skip은 얼마인가요?', ['언제나 2 그대로예요', '3이에요'], '정답은 두 번째예요. 원문은 skipnr+1을 넣어요. 호출자가 요청한 두 개에 수집 함수 자신을 제외할 하나를 더해요.'), ('stack_trace_save는 스케줄러 주소를 제외하는 nosched 콜백을 선택하나요?', ['아니요. 일반 consume 콜백을 선택해요', '네. 태스크 수집 경로와 항상 같아요'], '정답은 첫 번째예요. 함수 포인터의 실제 값은 stack_trace_consume_entry예요. 비슷한 저장 함수라도 어떤 콜백을 넘기는지 확인해야 해요.')]), 'os1950': ('남의 공책을 읽는 동안 공책이 치워지지 않도록 먼저 사용 허락을 받아요. 다 읽으면 허락을 돌려주되, 허락을 못 받았다면 돌려줄 것도 없어요.', '태스크 비교에 따른 skip과 스택 사용 수명의 짝을 이해합니다.', '확보 실패 → 0 반환, 확보 성공 → 탐색 → put → 저장 개수 반환의 두 경로를 그리세요.', ['stack_trace_save_tsk는 tsk로 지정한 태스크의 스택을 수집해요. skip은 skipnr+(current==tsk)로 계산해요. C의 == 비교는 같으면 1, 다르면 0이에요. 현재 태스크 자신일 때만 추가 한 항목을 제외해요.', 'skipnr=2라면 현재 태스크를 고를 때 skip은 3, 다른 태스크를 고를 때는 2예요. 이 경로는 nosched 콜백을 사용하므로 스케줄러 주소 필터도 적용해요. 필터된 주소는 일반 skip 감소에 포함되지 않아요.', '탐색 전에 try_get_task_stack을 불러 스택을 사용할 수 있는지 확보해요. 얻지 못하면 바로 0을 반환하고 walker와 put_task_stack을 호출하지 않아요. 얻지 않은 것을 반납하면 사용 권리 수가 맞지 않기 때문이에요.', '확보했다면 arch_stack_walk에 tsk와 NULL regs를 넘겨 탐색하고, 돌아오면 put_task_stack으로 사용을 마무리해요. 이후 실제 저장 개수를 반환해요. 저장 개수가 0이어도 확보에 성공했던 경로라면 반납 호출을 거쳐요.', '스택 참조는 읽는 동안 스택 메모리 수명을 지키기 위한 약속이에요. 이 약속을 얻었다고 대상 태스크의 실행이 자동으로 멈추거나 스택 내용이 더는 바뀌지 않는 것은 아니에요. 메모리가 남아 있는 조건과 내용이 안정된 조건을 구별해야 해요.', '참조 helper의 구체적인 동작은 커널 설정에 따라 달라요. 어떤 경로는 참조 수를 올리고 다른 경로는 스택 주소를 돌려주며 put이 빈 함수예요. 공통 wrapper는 같은 확보·반납 인터페이스를 사용해요. 모든 설정에서 동일한 참조 수 연산이 반드시 실행된다고 단정하지 않아요.'], [('다른 태스크를 수집할 때 current==tsk가 skipnr에 더하는 값은 얼마인가요?', ['언제나 1이에요', '0이에요'], '정답은 두 번째예요. 서로 다른 태스크를 가리키면 비교가 거짓이라 0이에요. 자기 자신의 태스크일 때만 1을 더해요.'), ('try_get_task_stack이 실패하면 이 wrapper가 put_task_stack도 부르나요?', ['아니요. 0을 반환하며 바로 끝나요', '네. 얻었는지와 관계없이 반납해요'], '정답은 첫 번째예요. 실패 분기의 return이 탐색과 반납보다 앞에 있어요. 확보한 경로만 대응하는 반납을 해야 해요.')]), 'os1951': ('지금 위치에서 길을 추적하는 것과 저장된 위치에서 시작하는 것은 달라요. 출발점이 다른 함수에 같은 건너뛰기 규칙을 무조건 적용하지 않아요.', 'regs 경로의 skip과 인수 전달을 현재 스택 경로와 비교합니다.', '같은 skipnr 2라도 일반 save는 3, save_regs는 2라고 적으세요. regs 경로의 인수는 current와 regs예요.', ['stack_trace_save_regs는 저장된 CPU 레지스터 상태를 바탕으로 스택을 수집해요. 레지스터는 CPU가 실행 상태를 담는 자리이고 pt_regs는 그 상태를 저장한 구조체예요. 실제 출발점의 해석은 CPU별 walker가 맡아요.', '이 함수는 cookie.skip에 skipnr를 그대로 넣어요. 일반 stack_trace_save처럼 1을 더하지 않아요. 현재 수집 함수가 시작점인 경로와 저장된 레지스터를 시작점으로 전달하는 경로의 정책을 구별해요.', 'skipnr=2이면 실제 skip도 2예요. 용량이 충분하고 walker가 A·B·C·D라는 합성 주소를 준다고 하면 A·B를 건너뛰고 C부터 저장해요. 같은 가상 목록에서 일반 save의 skip 3과 비교하면 왜 초기식 확인이 필요한지 볼 수 있어요.', '콜백은 일반 stack_trace_consume_entry예요. nosched 필터를 따로 선택하지 않아요. arch_stack_walk 호출에는 current와 전달받은 regs를 넣어요. regs는 배열 인덱스를 뜻하는 수가 아니라 저장된 실행 상태의 주소예요.', '이 wrapper 본문에는 try_get_task_stack이나 put_task_stack 호출이 없어요. 별도 태스크를 수집하는 함수에 그 호출이 있다고 여기에도 있다고 추측하지 않아요. 공통으로 비슷한 모양이라도 실제 호출 목록은 다를 수 있어요.', '그렇다고 아무 regs 주소나 넘겨도 안전하다는 뜻은 아니에요. 호출한 쪽은 레지스터 정보와 관련 스택이 유효한 상황을 마련해야 해요. 반환값은 c.len이며 실제 저장한 항목 개수만 결과로 읽어요.'], [('regs 기반 수집에서 cookie.skip은 skipnr에 얼마를 더하나요?', ['항상 1을 더해요', '추가하지 않고 그대로 써요'], '정답은 두 번째예요. 초기식은 .skip=skipnr예요. 일반 현재 스택 수집의 +1을 이 함수에도 그대로 적용하면 한 항목을 더 건너뛰게 돼요.'), ('이 regs wrapper 본문에 try_get_task_stack 호출이 있나요?', ['아니요. 이 본문에는 없어요', '네. 모든 수집 wrapper가 똑같이 호출해요'], '정답은 첫 번째예요. 상태 준비 뒤 arch_stack_walk를 부르고 개수를 반환해요. 호출이 없다는 사실은 유효하지 않은 포인터도 허용한다는 보장은 아니에요.')]), 'os1952': ('답안에 몇 줄이 적혔어도 검산에서 오류가 나면 맞는 답으로 제출할 수 없어요. 신뢰성 검사를 하는 스택 수집도 일부 주소와 성공 결과를 구분해요.', 'reliable 오류 반환과 성공 개수, 참조 반납 순서를 이해합니다.', 'walker가 주소 두 개를 쓴 뒤 -EIO라면 put 뒤 오류를 반환한다고 적으세요. 같은 두 개에 오류 0이면 결과 개수 2예요.', ['reliable은 신뢰할 수 있다는 뜻이에요. stack_trace_save_tsk_reliable은 CPU별 arch_stack_walk_reliable에 수집과 신뢰성 판정을 맡겨요. 반환형 int는 성공한 개수뿐 아니라 음수 오류도 나타낼 수 있어요.', '수집 상태는 일반 콜백을 사용하며 초기화에서 생략한 skip과 len은 0이에요. 먼저 try_get_task_stack을 시도하고 스택을 얻지 못하면 0을 반환해요. 원문은 스택이 없는 태스크의 경로를 신뢰할 수 있게 비어 있는 것으로 다뤄요.', '확보한 경우 walker를 부른 뒤 결과 ret를 받으며, 그다음 put_task_stack을 먼저 호출해요. walker 결과가 성공인지 오류인지와 관계없이 얻은 스택 사용을 마무리하는 순서예요. 실패했다고 반납을 빼먹으면 안 돼요.', '마지막 식 ret ? ret : c.len은 ret가 0이 아니면 ret를, 0이면 저장 개수를 고르는 뜻이에요. 정상 계약에서 음수 오류가 왔다면 오류를 전달하고, walker가 0으로 성공하면 실제 저장 개수를 돌려줘요.', '가상 walker가 주소 두 개를 쓴 뒤 -EIO라는 오류를 줬다고 해요. EIO는 오류 이름이고 여기서는 일부 수집 뒤 실패하는 예로 고른 값이에요. 결과 배열에 값이 보여도 신뢰 가능한 두 개 수집 성공으로 취급하면 안 돼요. 호출 결과를 int로 받아 음수 오류부터 확인해요.', '다른 태스크를 reliable 방식으로 살필 때는 호출한 쪽이 그 태스크가 실행 중이지 않도록 보장해야 한다는 계약도 있어요. 스택 참조 확보가 태스크를 자동 정지시키지는 않아요. 공통 함수의 오류 전달을 읽는 일과 CPU별 신뢰성 판정 자체를 검증하는 일은 구분해요.'], [('reliable walker가 일부 주소를 쓴 뒤 오류를 반환했어요. 배열에 값이 있으니 성공인가요?', ['네. 주소가 하나라도 있으면 성공이에요', '아니요. 반환된 오류를 처리해야 해요'], '정답은 두 번째예요. 부분 수집과 신뢰성 검증 성공은 달라요. wrapper는 오류를 우선 돌려주므로 결과를 성공 개수처럼 읽으면 안 돼요.'), ('스택 확보에 성공한 뒤 walker가 오류를 줘도 put_task_stack을 부르나요?', ['네. 결과를 고르기 전에 반납해요', '아니요. 성공일 때만 반납해요'], '정답은 첫 번째예요. 원문 순서는 walker 호출, put, 반환값 선택이에요. 사용 수명 정리와 수집 성공 여부는 별개의 책임이에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_483.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
